            raise ValueError(f"{event!r} is not an order event")
        target = self._moves[self.state].get(event)
        if target is None:
            self.log.append(f"ignored {event} in {self.state}")
            return
        self.log.append(f"{self.state} -> {target}")
        self.state = target


